/* 말끝 바꾸기 (쥬비 ~다비, 모모 ~니닷, 바리에 ~요오, 네티 ~용) */
const TIC_FX = {
  bi:   (t) => t.replace(/(어|야|아|지|다|게|자|해|까|네|냐|래|봐|와)(?=[!?.~⋯…]+(\s|$)|$)/g, "$1비"),
  momo: (t) => t.replace(/니다(?=[!.~]*(\s|$))/g, "니닷").replace(/니까(?=[?]*(\s|$))/g, "니깟"),
  yoo:  (t) => t.replace(/요(?=[!.~]*(\s|$))/g, "요오"),
  yong: (t) => t.replace(/요(?=[!.~]*(\s|$))/g, "용"),
};
function voiceOf(id) { return (typeof SADO_VOICE !== "undefined" && SADO_VOICE[id]) || null; }
/* 사도 말투로 공부 대사 */
function toneLines(id, kind) {
  const v = voiceOf(id); if (!v) return [];
  const set = (v.t && TIC_LINES[v.t]) || TONE_LINES[v.s] || TONE_LINES.jon;
  const fx = (v.t && TIC_FX[v.t]) || ((t) => t);
  return (set[kind] || []).map((t) => fx(t.replace(/\{c\}/g, v.c)));
}
function ticText(id, t) { const v = voiceOf(id); return v && v.t && TIC_FX[v.t] ? TIC_FX[v.t](t) : t; }
